function strideM(cm){ return cm*0.415/100; } // 步幅≈身高×0.415
function distanceKm(steps, cm){ return steps*strideM(cm)/1000; }
function calories(distanceKm, kg){ return distanceKm*kg*0.9; } // 步行 ~0.9 kcal/kg/km
var EXPORTS={strideM:strideM, distanceKm:distanceKm, calories:calories};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StepsForgePure = EXPORTS; }
